// Reserved fixture families. Do not import during development or validation.
const u = (text, session) => session === undefined ? ['user', text] : ['user', text, session];
const a = (text) => ['assistant', text];
const t = (text) => ['tool', text];
const s = (text) => ['subagent', text];
const C = 'continue_current';
const S = 'switch_existing';
const N = 'create_new';
const O = 'no_task';
const U = 'uncertain';
const high = { risk: 'high' };
const reopen = { retrievalTarget: 'b', unresolved: ['closed-target-needs-review'] };

function group(family, rows) {
  return rows.map(([language, intent, taskEntries, turns, options = {}]) => {
    const tasks = taskEntries.map((entry, index) => ({
      key: String.fromCharCode(97 + index),
      ...(typeof entry === 'string' ? { title: entry } : entry),
    }));
    const binding = Object.hasOwn(options, 'binding') ? options.binding : (tasks.length ? 'a' : null);
    return {
      family, split: 'holdout', language, tasks, turns, binding, intent,
      target: intent === C ? binding : intent === S ? 'b' : null,
      labelProvenance: 'ai_provisional_not_human_reviewed',
      ...options,
    };
  });
}

